int main(){ios::sync_with_stdio(false);cin.tie(nullptr);string line;while(getline(cin,line)){json input=json::parse(line);CwContext cw;auto result=Solution().solve(cw.list(input.at("head")),input.at("k").get<int>());cout<<json(cw.list_values(result)).dump()<<"\n";cw.list_cleanup(result);}}
